package com.ittxf.leetcode.hot100.p438_findallanagramsinastring;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;

public class LeetCode438_FindAllAnagramsInAString {
    public static void main(String[] args) {
        String s = "";
        String p = "yqrbgjdwtcaxzsnifvhmou";
        System.out.println(new Solution().findAnagrams(s, p));
    }
}

class Solution {
    public List<Integer> findAnagrams(String s, String p) {
        List<Integer> result = new ArrayList<>();
        if (s == null || s.length() < p.length()) return result;

        // 记录 p 中每个字母需要的频次
        int[] need = new int[26];
        for (char c : p.toCharArray()) {
            need[c - 'a']++; // 0 - 25
        }

        int left = 0; // 窗口左边界
        int matchCount = 0; // 记录当前窗口内，已经和 p 匹配上的字符总数

        for (int right = 0; right < s.length(); right++) {
            char rightChar = s.charAt(right);
            // 1. 如果这个字符是 p 需要的，匹配数 +1
            if (need[rightChar - 'a'] > 0) {
                matchCount++;
            }
            // 2. 把它纳入窗口，需要的频次 -1
            need[rightChar - 'a']--;

            // 3. 如果窗口长度达到了 p 的长度，开始收缩窗口
            if (right - left + 1 == p.length()) {
                // 如果匹配数刚好等于 p 的长度，说明全匹配上了，记录起始索引
                if (matchCount == p.length()) result.add(left);

                // 此时要准备把左边界移出窗口，恢复频次
                char leftChar = s.charAt(left);
                // 如果要移出的字符是 p 需要的，匹配数 -1
                if (need[leftChar - 'a'] >= 0) matchCount--;
                // 移出窗口，恢复需要的频次
                need[leftChar - 'a']++;
                left++; // 左边界右移
            }
        }
        return result;

        /*char[] pArr = p.toCharArray();
        Arrays.sort(pArr);
        int len = p.length() - 1;
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < s.length() - len; i++) {
            String sub = s.substring(i, i + len + 1);
            char[] sArr = sub.toCharArray();
            Arrays.sort(sArr);
            if (Arrays.equals(sArr, pArr)) result.add(i);
        }
        return result;*/
    }
}

